// t489 probe: what one save in a large worktree costs the reads that follow it,
// and what a read limited to the changed path would cost.
use std::time::Instant;

fn ms(t: Instant) -> f64 { t.elapsed().as_secs_f64() * 1000.0 }

fn status(path: &str, renames: bool, only: Option<&str>) -> usize {
    let repo = git2::Repository::open(path).unwrap();
    let mut opts = trunk_git::status::dirty_status_options();
    if renames { opts.renames_head_to_index(true); }
    if let Some(p) = only { opts.pathspec(p); opts.disable_pathspec_match(true); }
    repo.statuses(Some(&mut opts)).unwrap().len()
}

fn wip_diff(path: &str, only: Option<&str>) -> usize {
    let repo = git2::Repository::open(path).unwrap();
    let head = repo.head().unwrap().peel_to_tree().unwrap();
    let mut s = git2::DiffOptions::new();
    if let Some(p) = only { s.pathspec(p); s.disable_pathspec_match(true); }
    let staged = repo.diff_tree_to_index(Some(&head), None, Some(&mut s)).unwrap();
    let mut opts = git2::DiffOptions::new();
    opts.include_untracked(true).recurse_untracked_dirs(true).show_untracked_content(true);
    if let Some(p) = only { opts.pathspec(p); opts.disable_pathspec_match(true); }
    let unstaged = repo.diff_index_to_workdir(None, Some(&mut opts)).unwrap();
    staged.stats().unwrap().files_changed() + unstaged.stats().unwrap().files_changed()
}

fn capture(path: &str) -> usize {
    let mut repo = git2::Repository::open(path).unwrap();
    let memo = trunk_git::graph::CommitMemo::default();
    drop(trunk_git::graph::capture_remembering(&mut repo, &memo).unwrap());
    0
}

fn main() {
    let path = std::env::args().nth(1).unwrap();
    let one = "src/d000/f00007.txt";
    if std::env::args().nth(2).as_deref() == Some("mixes") { mixes(&path); return; }
    if std::env::args().nth(2).as_deref() == Some("loop") { for _ in 0..15 { status(&path, false, None); } return; }
    for round in 0..5 {
        let t = Instant::now(); drop(git2::Repository::open(&path).unwrap().index().unwrap()); let open = ms(t);
        let t = Instant::now(); let n = status(&path, true, None); let st = ms(t);
        let t = Instant::now(); status(&path, false, None); let dirty = ms(t);
        let t = Instant::now(); wip_diff(&path, None); let wip = ms(t);
        let t = Instant::now(); capture(&path); let cap = ms(t);
        let t = Instant::now(); let n1 = status(&path, true, Some(one)); let st1 = ms(t);
        let t = Instant::now(); wip_diff(&path, Some(one)); let wip1 = ms(t);
        let t = Instant::now();
        let p = path.clone();
        let threads: Vec<_> = (0..4).map(|i| { let p = p.clone(); std::thread::spawn(move || match i { 0 => status(&p, true, None), 1 => status(&p, false, None), 2 => wip_diff(&p, None), _ => capture(&p) }) }).collect();
        let mut first = 0.0;
        for (i, h) in threads.into_iter().enumerate() { h.join().unwrap(); if i == 0 { first = ms(t); } }
        let together = ms(t);
        println!("round {round}: entries {n} index {open:.1} status {st:.1} dirty {dirty:.1} wipdiff {wip:.1} capture {cap:.1} | one-path status {st1:.2} ({n1}) wipdiff {wip1:.2} | four together {together:.1}, status among them {first:.1}");
    }
}

// Status latency when it runs beside the other readers of a save. 0 status (renames),
// 1 counts (renames), 2 graph dirtiness (no renames), 3 wip diff.
fn mixes(path: &str) {
    let sets: [(&str, &[u8]); 5] = [("status+counts+dirty+wip", &[0, 1, 2, 3]), ("status+dirty+wip", &[0, 2, 3]), ("status+wip", &[0, 3]), ("wip alone", &[3]), ("status alone", &[0])];
    for round in 0..5 {
        let mut line = format!("round {round}:"); let _ = 0;
        for (name, set) in sets {
            let t = Instant::now();
            let threads: Vec<_> = set.iter().map(|&i| { let p = path.to_owned(); std::thread::spawn(move || { match i { 0 | 1 => { status(&p, true, None); } 2 => { status(&p, false, None); } _ => { wip_diff(&p, None); } } ms(t) }) }).collect();
            let times: Vec<f64> = threads.into_iter().map(|h| h.join().unwrap()).collect();
            let all = ms(t);
            line += &format!(" | {name}: status {:.1} all {:.1}", times[0], all);
        }
        println!("{line}");
    }
}
